    #[test]
    fn visited_method_chain_emits_panic_facts_for_each_callsite() {
        let src = r#"
            #[test]
            fn visited_chain() {
                [1..3].iter().next().next().next();
            }
        "#;
        let out = lift_src(src);
        assert_eq!(
            out.assertions_lifted, 0,
            "non-panic method chain facts do not increment scalar assertion count"
        );
        let panic_fact_contracts: Vec<&str> = out
            .assertion_facts
            .iter()
            .filter(|fact| fact.kind == AssertionFactKind::Warranted)
            .map(|fact| fact.contract_name.as_str())
            .collect();
        assert_eq!(
            panic_fact_contracts.len(),
            4,
            "iter + three next calls should each emit one warranted non-panic fact: {panic_fact_contracts:?}"
        );
        assert!(
            panic_fact_contracts
                .iter()
                .any(|contract| contract.contains("method:iter")),
            "the iterator construction callsite must be warranted: {panic_fact_contracts:?}"
        );
        assert_eq!(
            panic_fact_contracts
                .iter()
                .filter(|contract| contract.contains("method:next"))
                .count(),
            3,
            "each next callsite now owns its opaque method subject for panic(Int) support: {panic_fact_contracts:?}"
        );
        assert!(
            std::collections::BTreeSet::<&str>::from_iter(panic_fact_contracts.iter().copied())
                .len()
                == panic_fact_contracts.len(),
            "opaque method callsite identities must distinguish the chain callsites: {panic_fact_contracts:?}"
        );
        let no_panic_facts = out
            .factory_audits
            .iter()
            .filter(|audit| {
                audit.requested_role == "SupportConstraint"
                    && audit.selected == Some("constraint_no_panic_call")
                    && audit.disposition == FactoryDisposition::Warranted
            })
            .count();
        assert_eq!(
            no_panic_facts, 4,
            "every visited chain callsite should route through NoPanicCallSugar: {:?}",
            out.factory_audits
        );
    }

    #[test]
    fn disjoint_mut_assign_ops_temporally_rewrite_literal_vector() {
        let src = r#"
            #[test]
            fn disjoint_mut_rewrite() {
                let mut v = vec![1, 2, 3];
                let [a, b] = v.get_disjoint_mut([2, 0]).unwrap();
                *a += 10;
                *b += 100;
                assert_eq!(v, vec![101, 2, 13]);
            }
        "#;
        let out = lift_src(src);
        assert_eq!(
            out.assertions_refused, 0,
            "literal-backed temporal rewrites must not leave assignment residue: {:?}",
            out.skip_reasons
        );
        let unresolved_updates: Vec<_> = out
            .factory_audits
            .iter()
            .filter(|audit| {
                audit.requested_role == "Constraint"
                    && audit.disposition == FactoryDisposition::Unresolved
                    && audit.site.contains("+=")
            })
            .collect();
        assert!(
            unresolved_updates.is_empty(),
            "compound assignment statements should be owned by temporal rewrite sugar: {unresolved_updates:?}"
        );
        let dump = format!("{:?}", out.decls);
        assert!(
            dump.contains("101") && dump.contains("13"),
            "the final assertion should read the rewritten vector literal, not the pre-update binding: {dump}"
        );
        assert!(
            !dump.contains("name: \"v@def") && !dump.contains("name: \"v\""),
            "the final assertion should not freeze the mutable vector as an opaque temporal var: {dump}"
        );
    }

