    #[test]
    fn source_shaped_method_assertion_lifts_without_method_name_whitelist() {
        // The method name is not semantic. The shape is semantic: the method source is
        // visible, its body is constraint-shaped, and the collector re-digs that body at
        // the call site.
        let src = r#"
            fn value() -> i32 { 3 }

            struct Expect {
                actual: i32,
            }

            impl Expect {
                fn totally_not_a_magic_name(self, expected: i32) {
                    if self.actual != expected {
                        panic!("bad");
                    }
                }

                fn still_not_vocabulary(self, forbidden: i32) {
                    assert_ne!(self.actual, forbidden);
                }
            }

            #[test]
            fn method_constraint() {
                Expect { actual: value() }.totally_not_a_magic_name(3);
                Expect { actual: value() }.still_not_vocabulary(4);
            }
        "#;
        let out = lift_src(src);
        assert!(
            out.assertion_facts.iter().any(|fact| fact.kind == AssertionFactKind::Warranted
                && fact
                    .contract_name
                    .starts_with("method:totally_not_a_magic_name#")),
            "visible if-panic method body should be re-dug as a warranted fact by shape, not by method name: {:?}",
            out.assertion_facts
        );
        assert!(
            out.assertion_facts.iter().any(|fact| fact.kind == AssertionFactKind::Warranted
                && fact
                    .contract_name
                    .starts_with("method:still_not_vocabulary#")),
            "visible assert macro method body should be re-dug as a warranted fact by shape, not by method name: {:?}",
            out.assertion_facts
        );
        assert_eq!(out.assertions_refused, 0, "{:?}", out.skip_reasons);
    }

    #[test]
    fn const_item_conditional_assert_is_not_falsely_lifted() {
        // NEGATIVE TWIN: an assert that sits under a `for` loop INSIDE the const
        // item block is genuinely conditional (per-element). Recursing into the
        // const-item block must NOT promote it to a point-wise lift -- the
        // per-assert gating still routes it to the for-context refusal. Over-
        // claiming it would be a false discharge.
        // Vendor shape: rust-src coretests iter/mod.rs::test_const_iter.
        let src = r#"
            #[test]
            fn const_loop() {
                const X: bool = {
                    let it = Some(42);
                    let mut run = false;
                    for x in it {
                        assert!(x == 42);
                        run = true;
                    }
                    run
                };
                assert!(X);
            }
        "#;
        let out = lift_src(src);
        // The `assert!(x == 42)` under the `for` must stay refused (conditional);
        // only the unconditional top-level `assert!(X)` lifts.
        assert!(
            out.skip_reasons
                .iter()
                .any(|r| r.contains("under for context")),
            "the for-bodied assert inside the const block must stay refused as a \
             for-context assertion, not be falsely lifted: {:?}",
            out.skip_reasons
        );
        assert!(
            out.assertions_lifted <= 1,
            "only the unconditional `assert!(X)` may lift, not the conditional \
             for-body assert: lifted={}, reasons={:?}",
            out.assertions_lifted,
            out.skip_reasons
        );
    }

